def _get_recipe_reference(reference):
    try:
        ref = RecipeReference.loads(reference)
        if not ref.revision:
            return None
        return ref
    except ConanException:
        return None


def _get_package_reference(pref):
    try:
        pref = PkgReference.loads(pref)
        if not pref.revision or not pref.ref.revision:
            return None
        return pref
    except ConanException:
        return None
